    for(const [el,aria] of bulkGuards)if(!guards.has(el)){el.classList.remove('s2wc-search-bulk-guard');if(aria===null)el.removeAttribute('aria-disabled');else el.setAttribute('aria-disabled',aria);bulkGuards.delete(el);}
