  actions.append(button('显示工具栏','panel',()=>openNative(),'s2wc-im-tool'));
  list.querySelector('.s2wc-im-add').onclick=()=>{input.value='';listFingerprint='';update();input.focus();};
  input.oninput=()=>{listFingerprint='';renderList();};
